/* eslint-disable eqeqeq */
import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { IonContent, AlertController, LoadingController, ToastController } from '@ionic/angular';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { G } from '../../../../core/common/G';
import { GAccount } from '../../../../core/common/GAccount';
import { SliderService } from '../../../../data/service/site/Slider.service';
import { CourseService } from '../../../../data/service/course/course.service';
import { Urls } from '../../../../core/common/Urls';
import { GResponse } from '../../../../core/common/GResponse';

@Component({
  selector: 'app-hp',
  templateUrl: './hp.component.html',
  styleUrls: ['./hp.component.scss']
})
export class HPComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  tunerPlusVideo: string | SafeUrl = 'Gywn6';

  form: FormGroup;
  form2: FormGroup;
  form3: FormGroup;
  pwr = 60.76;
  hp = 110;
  power = 82.03;
  t = 131;
  torque = 96.61;
  hpType = '1';
  torqueType = '1';

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService
  ) {
    this.isShow = false;
    if (!GAccount.IsLoggedIn()) {
      this.router.navigateByUrl('/Account');
    }
    this.check();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(6).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.tunerPlusVideo = G.TunerPlusHpVideo;

    this.form = this.fb.group({
      hp: [110, [Validators.required, Validators.min(1), Validators.max(1000)]],
      rpm: [6000, [Validators.required, Validators.min(1), Validators.max(1000000)]]
    });

    this.form2 = this.fb.group({
      t: [131, [Validators.required, Validators.min(1), Validators.max(1000)]],
      rpm: [6000, [Validators.required, Validators.min(1), Validators.max(1000000)]]
    });

    this.form3 = this.fb.group({
      hp: [110, [Validators.required, Validators.min(1), Validators.max(1000)]],
      kg: [1350, [Validators.required, Validators.min(1), Validators.max(1000000)]]
    });
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    let typeValue = 1;

    if (this.hpType == '1') {

      typeValue = 1;
      this.power = +(this.form.value.hp * 0.7457).toFixed(2);
    } else {

      typeValue = 0.7457;
      this.power = +(this.form.value.hp / 0.7457).toFixed(2);
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {


          this.t = Math.round(this.form.value.hp / typeValue / this.form.value.rpm * 5252 * 1.3558179999442195);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );

  }

  onReset() {

    this.t = 131;
    this.power = 82.03;
    this.hpType = '1';
    this.form.setValue({
      hp: 110,
      rpm: 6000
    });
  }

  onCalc2() {

    if (!this.form2.valid) {

      return;
    }

    let typeValue = 1;


    if (this.torqueType == '1') {

      typeValue = 1;
      this.torque = +(this.form2.value.t / 1.356).toFixed(2);
    } else {

      typeValue = 1.356;
      this.torque = +(this.form2.value.t * 1.356).toFixed(2);
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          this.hp = Math.round(((this.form2.value.t * typeValue) / 1.3558179999442195 * this.form2.value.rpm) / 5252);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onCalc3() {

    if (!this.form3.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          this.pwr = +((+this.form3.value.hp * 0.7456998658 * 1000) / (+this.form3.value.kg)).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onReset2() {

    this.hp = 110;
    this.torque = 96.61;
    this.torqueType = '1';
    this.form2.setValue({
      t: 131,
      rpm: 6000
    });
  }

  onReset3() {

    this.pwr = 60.76;
    this.form3.setValue({
      hp: 110,
      kg: 1350
    });
  }

  onInfo(type: string) {

    switch (type) {
      case 'hp':
        this.presentActiveAlertConfirm('توان موتور');
        break;
      case 't':
        this.presentActiveAlertConfirm('گشتاور موتور');
        break;
      case 'rpm':
        this.presentActiveAlertConfirm('دور موتوری که توان یا گشتاور را می خواهید حساب کنید');
        break;
      case 'kg':
        this.presentActiveAlertConfirm('وزن خودرو برحسب کیلوگرم');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

}
